"""Turn flow: Play Villain Card (city advance, escapes, Bystanders, Twists, Strikes) and End Turn (discard, draw 6, reset counters, refill HQ)."""

# mat objects' printed-area maths must match build_save.py
PM_BOARD_H = 25.57
PM_PRINTED = 26.9 / 29.4
PM_ASPECT = 2400 / 1697.7
PILES = {'draw': (.18, .50), 'victory': (.50, .22), 'discard': (.82, .50)}
ATTACK_COUNTERS = ['de4eb3', '2a7e51', '2745ea', 'e26e29', '924dcd']
RECRUIT_COUNTERS = ['82ac8c', 'dfa0d0', '2a6096', '4cf94b', '30a81a']

TURN_LUA = r'''
--[[ ===== Turn flow: villain card, end turn, HQ refill (generated by the save builder) ===== --]]
TURN = {busy = false}
PM = {board_h = __PMH__, printed = __PMP__, aspect = __PMA__}
PILES = {draw = {__DRAW__}, victory = {__VICT__}, discard = {__DISC__}}
ATTACK_COUNTERS = {__ATT__}
RECRUIT_COUNTERS = {__REC__}

function tfWait(n) for i = 1, n do coroutine.yield(0) end end

function tfSay(msg, color)
    pcall(function() broadcastToAll(msg, color or {0.9, 0.9, 0.5}) end)
    print(msg)
end

--[[Cards and decks within a box on the table--]]
function tfAt(x, z, rx, rz)
    local out = {}
    for _, o in ipairs(getObjects()) do
        local ok, kind = pcall(function() return o.type end)
        if ok and (kind == "Card" or kind == "Deck") then
            local p = o.getPosition()
            if math.abs(p.x - x) <= rx and math.abs(p.z - z) <= rz and p.y < 8 then out[#out + 1] = o end
        end
    end
    return out
end

function tfCityCell(i) return tfAt(CITYX[i], CITYZ, 1.35, 2.0) end
function tfHqCell(i) return tfAt(HQX[i], HQZ, 1.35, 2.0) end

function tfMove(o, x, y, z)
    pcall(function() o.setPositionSmooth({x, y, z}, false, true) end)
end

function tfCtrPlayed()
    local r = CTR_RULES[MENU.drawn.scheme or ""] or {}
    local i = 1
    for k, t in ipairs(r) do if t.k == "twist" then i = k end end
    for k, t in ipairs(CTR.list or {}) do if t.k == "twist" then i = k break end end
    local row = (CTR.list or {})[i]
    if row == nil then return nil end
    local auto, adj = ctrValue(i, row)
    return (auto or 0) + (adj or 0)
end

--[[The lines of the drawn scheme's text that apply to Twist number n--]]
function tfTwistText(n)
    local e = refEntry("schemes", MENU.drawn.scheme)
    if e == nil then return nil end
    local out = {}
    for _, line in ipairs(splitLines(e.t)) do
        if string.sub(line, 1, 5) == "Twist" then
            local colon = string.find(line, ":", 1, true)
            if colon ~= nil then
                local prefix = string.sub(line, 1, colon - 1)
                local nums = {}
                for d in string.gmatch(prefix, "%d+") do nums[#nums + 1] = tonumber(d) end
                local hit = false
                if #nums == 0 then hit = true
                elseif string.find(prefix, "-", 1, true) and #nums >= 2 then hit = (n >= nums[1] and n <= nums[2])
                else for _, v in ipairs(nums) do if v == n then hit = true end end end
                if hit then out[#out + 1] = line end
            end
        end
    end
    if #out == 0 then return nil end
    return table.concat(out, "\n")
end

function tfStrikeText()
    local out = {}
    local names = {MENU.drawn.mastermind}
    for _, nm in ipairs(MENU.drawn.extraMM or {}) do names[#names + 1] = nm end
    for k, nm in ipairs(names) do
        local e = refEntry("masterminds", nm)
        if e ~= nil then
            for _, line in ipairs(splitLines(e.t)) do
                if string.sub(line, 1, 14) == "Master Strike:" then
                    out[#out + 1] = (k == 1) and line or (nm .. " - " .. line)
                    break
                end
            end
        end
    end
    if #out == 0 then return nil end
    return table.concat(out, "\n")
end

function tfClassify(card)
    local ok, name = pcall(function() return card.getName() end)
    name = ok and name or ""
    if name == "Scheme Twist" then return "twist", name end
    if name == "Master Strike" then return "strike", name end
    local isBy = false
    pcall(function() isBy = card.hasTag("Bystander") end)
    if isBy then return "bystander", name end
    return "villain", name
end

function tfEscape(objs, label)
    local ex, ez = SLOTS.escape.x, SLOTS.escape.z
    local by = 0
    for k, o in ipairs(objs) do
        local t = newTally(); tallyObject(t, o); by = by + t.bystander
        tfMove(o, ex, 2 + 0.3 * k, ez)
    end
    local msg = (label or "A Villain") .. " escapes! KO a Hero that costs 6 or less from the HQ."
    if by > 0 then msg = msg .. " It carried Bystanders: each player discards a card." end
    tfSay(msg, {1, 0.5, 0.4})
end

--[[Moves every occupied city space forward one space (only as far as the chain of occupied spaces goes)--]]
function tfAdvanceCity()
    local cells, k = {}, 0
    for i = 1, 5 do cells[i] = tfCityCell(i) end
    while k < 5 and #cells[k + 1] > 0 do k = k + 1 end
    if k == 0 then return end
    if k == 5 then
        tfEscape(cells[5], "A Villain")
        k = 4
    end
    for i = k, 1, -1 do
        local dx = CITYX[i + 1] - CITYX[i]
        for _, o in ipairs(cells[i]) do
            local p = o.getPosition()
            tfMove(o, p.x + dx, p.y, p.z)
        end
    end
end

function tfPlayVillain(isExtra)
    local vd = findDeckByName("Villain Deck")
    if vd == nil then tfSay("No Villain Deck on the table. Run Setup first.") return end
    local stage = {CITYX[1], 3.5, CITYZ + 3.4}
    local got = nil
    pcall(function()
        vd.takeObject({position = stage, rotation = {0, 180, 0}, smooth = false, callback_function = function(o) got = o end})
    end)
    for i = 1, 90 do if got ~= nil then break end coroutine.yield(0) end
    if got == nil then tfSay("Could not take a card from the Villain Deck.") return end
    local kind, name = tfClassify(got)
    if kind == "villain" then
        tfAdvanceCity()
        tfWait(40)
        tfMove(got, CITYX[1], 2, CITYZ)
        tfWait(60)
        tfSay((isExtra and "Extra card: " or "Villain deck: ") .. name .. " enters the Sewers. Do its Ambush effect if it has one.")
    elseif kind == "bystander" then
        local target
        for i = 1, 5 do
            local c = tfCityCell(i)
            if #c > 0 then target = {CITYX[i], CITYZ} break end
        end
        if target ~= nil then
            tfMove(got, target[1] + 0.5, 2.2, target[2] - 1.0)
            tfWait(50)
            tfSay("Bystander captured by the Villain nearest the Villain Deck.")
        else
            tfMove(got, SLOTS.mastermind.x + 0.5, 2.2, SLOTS.mastermind.z - 1.0)
            tfWait(50)
            tfSay("No Villains in the city: the Mastermind captures the Bystander.")
        end
    elseif kind == "twist" then
        tfMove(got, SLOTS.villainko.x, 2.5, SLOTS.villainko.z)
        tfWait(40)
        local n = tfCtrPlayed()
        local txt = n and tfTwistText(n) or nil
        tfSay("SCHEME TWIST" .. (n and (" #" .. n) or "") .. (txt and (":\n" .. txt) or ". Resolve the Scheme's Twist text."), {1, 0.8, 0.3})
        if MENU.players == 1 then
            if MENU.advanced then tfSay("Advanced Solo: put a Hero of cost 6 or less from the HQ on the bottom of the Hero Deck.")
            else tfSay("Solo: KO a Hero of cost 6 or less from the HQ.") end
        end
    elseif kind == "strike" then
        tfMove(got, SLOTS.villainko.x, 2.5, SLOTS.villainko.z)
        tfWait(40)
        local txt = tfStrikeText()
        tfSay("MASTER STRIKE" .. (txt and (":\n" .. txt) or ". Resolve the Mastermind's Master Strike."), {1, 0.8, 0.3})
        if MENU.players == 1 and MENU.advanced and not isExtra then
            tfSay("Advanced Solo: play another card from the Villain Deck.")
            tfWait(60)
            tfPlayVillain(true)
        end
    end
end

function tfPlayVillainCo()
    if TURN.busy then return 1 end
    TURN.busy = true
    local ok, err = pcall(tfPlayVillain, false)
    tfWait(20)
    TURN.busy = false
    if not ok then print("Play Villain failed: " .. tostring(err)) end
    return 1
end

function onPlayVillain(player)
    if TURN.busy then tfSay("Still resolving the last card, wait a moment.") return end
    startLuaCoroutine(Global, "tfPlayVillainCo")
end

--[[ ---------- end turn ---------- --]]
function tfMatPoint(mat, uv)
    local p = mat.getPosition()
    local sc = mat.getScale().x
    local pw = PM.board_h * sc * PM.aspect * PM.printed
    local ph = PM.board_h * sc * PM.printed
    local lx, lz = (uv[1] - 0.5) * pw, -(uv[2] - 0.5) * ph
    local th = math.rad((mat.getRotation().y or 180) - 180)
    return {x = p.x + lx * math.cos(th) + lz * math.sin(th), z = p.z - lx * math.sin(th) + lz * math.cos(th)}, pw, ph
end

function tfNearestMat(p)
    local best, bd = nil, 1e9
    for _, g in ipairs(PLAYER_MATS) do
        local o = getObjectFromGUID(g)
        if o ~= nil then
            local q = o.getPosition()
            local d = (q.x - p.x) ^ 2 + (q.z - p.z) ^ 2
            if d < bd then best, bd = o, d end
        end
    end
    return best
end

function tfPileAt(pt)
    local c = tfAt(pt.x, pt.z, 2.2, 2.8)
    return c[1]
end

--[[The Attack and Recruit counters nearest a mat--]]
function tfMatCounters(matPos)
    local function nearest(list)
        local best, bd
        for _, g in ipairs(list) do
            local o = getObjectFromGUID(g)
            if o ~= nil then
                local q = o.getPosition()
                local d = (q.x - matPos.x) ^ 2 + (q.z - matPos.z) ^ 2
                if bd == nil or d < bd then best, bd = o, d end
            end
        end
        return best
    end
    return nearest(ATTACK_COUNTERS), nearest(RECRUIT_COUNTERS)
end

function tfResetCounters(matPos)
    local att, rec = tfMatCounters(matPos)
    for _, o in ipairs({att, rec}) do
        if o ~= nil then pcall(function() o.Counter.setValue(0) end) end
    end
end

function tfRefillHQ()
    local hd = findDeckByName("Hero Deck")
    if hd == nil then return 0 end
    local n = 0
    for i = 1, 5 do
        if #tfHqCell(i) == 0 then
            local deck = findDeckByName("Hero Deck")
            if deck == nil then break end
            pcall(function() deck.takeObject({position = {HQX[i], 2, HQZ}, rotation = {0, 180, 0}, smooth = true}) end)
            n = n + 1
            tfWait(15)
        end
    end
    return n
end

--[[The three pile points of a mat, and the printed area's size--]]
function tfMatPiles(mat)
    local draw, pw, ph = tfMatPoint(mat, PILES.draw)
    return draw, tfMatPoint(mat, PILES.victory), tfMatPoint(mat, PILES.discard), pw, ph
end

--[[Cards and decks played on a mat: inside its printed area (rotation-aware), not on the Draw / Victory / Discard piles--]]
function tfPlayedOn(mat)
    local matPos = mat.getPosition()
    local rotY = mat.getRotation().y or 180
    local draw, vict, disc, pw, ph = tfMatPiles(mat)
    local keepers = {draw, vict, disc}
    local out = {}
    local th = math.rad(rotY - 180)
    for _, o in ipairs(tfAt(matPos.x, matPos.z, pw / 2 + 0.5, pw / 2 + 0.5)) do
        local p = o.getPosition()
        local dx, dz = p.x - matPos.x, p.z - matPos.z
        local lx = dx * math.cos(th) - dz * math.sin(th)
        local lz = dx * math.sin(th) + dz * math.cos(th)
        local inside = math.abs(lx) <= pw / 2 + 0.3 and math.abs(lz) <= ph / 2 + 0.3
        local isPile = false
        for _, k in ipairs(keepers) do
            if (p.x - k.x) ^ 2 + (p.z - k.z) ^ 2 < 2.8 ^ 2 then isPile = true end
        end
        if inside and not isPile then out[#out + 1] = o end
    end
    return out
end

function tfEndTurn(player)
    local mat = nil
    local ok, h = pcall(function() return player.getHandTransform(1) end)
    if ok and h ~= nil and h.position ~= nil then mat = tfNearestMat({x = h.position.x or h.position[1], z = h.position.z or h.position[3]}) end
    if mat == nil then tfSay("Could not find your player mat.") return end
    local matPos = mat.getPosition()
    local rotY = mat.getRotation().y or 180
    local draw, vict, disc = tfMatPiles(mat)
    --[[everything to discard: the hand and the cards played on the mat--]]
    local todo = {}
    local seen = {}
    local okh, hand = pcall(function() return player.getHandObjects(1) end)
    if okh and hand ~= nil then for _, o in ipairs(hand) do todo[#todo + 1] = o; seen[o] = true end end
    for _, o in ipairs(tfPlayedOn(mat)) do
        if not seen[o] then todo[#todo + 1] = o; seen[o] = true end
    end
    local pile = tfPileAt(disc)
    local count = 0
    for _, o in ipairs(todo) do
        count = count + 1
        pcall(function() o.setRotation({0, rotY, 0}) end)
        if pile == nil then
            pile = o
            tfMove(o, disc.x, 2, disc.z)
            tfWait(25)
        else
            local okp, res = pcall(function() return pile.putObject(o) end)
            if okp and res ~= nil then pile = res end
            tfWait(8)
        end
    end
    tfWait(30)
    --[[draw a new hand of 6, reshuffling the discard pile when the deck runs short--]]
    local deckObj = tfPileAt(draw)
    local want = 6
    local function qty(o) local okq, q = pcall(function() return o.getQuantity() end) return okq and q or 1 end
    if deckObj ~= nil then
        local take = math.min(want, qty(deckObj))
        if take > 0 then pcall(function() deckObj.deal(take, player.color) end) end
        want = want - take
        tfWait(40)
    end
    if want > 0 then
        local d = tfPileAt(disc)
        if d ~= nil then
            tfSay("Reshuffling the discard pile into a new Draw Deck.")
            pcall(function() d.setPosition({draw.x, 2, draw.z}) end)
            pcall(function() d.setRotation({0, rotY, 180}) end)
            tfWait(40)
            pcall(function() d.shuffle() end)
            tfWait(40)
            local nd = tfPileAt(draw)
            if nd ~= nil then pcall(function() nd.deal(math.min(want, qty(nd)), player.color) end) end
            tfWait(30)
        end
    end
    tfResetCounters(matPos)
    local filled = tfRefillHQ()
    tfSay("End of turn: " .. count .. " cards discarded, new hand drawn, Attack and Recruit reset" .. ((filled > 0) and (", HQ refilled (" .. filled .. ")") or "") .. ".")
end

function tfEndTurnCo()
    if TURN.busy then return 1 end
    TURN.busy = true
    local ok, err = pcall(tfEndTurn, TURN.player)
    TURN.busy = false
    if not ok then print("End Turn failed: " .. tostring(err)) end
    pcall(plSchedule)
    return 1
end

function onEndTurn(player)
    if TURN.busy then tfSay("Still resolving, wait a moment.") return end
    TURN.player = (type(player) == "string") and Player[player] or player
    startLuaCoroutine(Global, "tfEndTurnCo")
end

function tfRefillCo()
    if TURN.busy then return 1 end
    TURN.busy = true
    pcall(tfRefillHQ)
    TURN.busy = false
    return 1
end

function onRefillHQ(player) startLuaCoroutine(Global, "tfRefillCo") end

function registerTurnHotkeys()
    pcall(function() addHotkey("Legendary: play villain card", function(c) onPlayVillain(c) end) end)
    pcall(function() addHotkey("Legendary: end turn", function(c) onEndTurn(c) end) end)
end
'''


def turn_lua():
    def pair(uv): return '%g, %g' % uv
    return (TURN_LUA.replace('__PMH__', '%g' % PM_BOARD_H).replace('__PMP__', '%.5f' % PM_PRINTED).replace('__PMA__', '%.5f' % PM_ASPECT)
            .replace('__DRAW__', pair(PILES['draw'])).replace('__VICT__', pair(PILES['victory'])).replace('__DISC__', pair(PILES['discard']))
            .replace('__ATT__', ', '.join('"%s"' % g for g in ATTACK_COUNTERS)).replace('__REC__', ', '.join('"%s"' % g for g in RECRUIT_COUNTERS)))
